def get_benchmarker(self):
    from triton.testing import do_bench
    return do_bench

def run(self, *args, **kwargs):
    self.nargs = dict(zip(self.arg_names, args))
    used_cached_result = True
    if len(self.configs) > 1:
        all_args = {**self.nargs, **kwargs}
        _args = {k: v for (k, v) in all_args.items() if k in self.arg_names}
        key = [_args[key] for key in self.keys if key in _args]
        for _, arg in _args.items():
            if hasattr(arg, "dtype"):
                key.append(str(arg.dtype))
        key = tuple(key)
        if key not in self.cache:
            # prune configs
            used_cached_result = False
            pruned_configs = self.prune_configs(kwargs)
            bench_start = time.time()
            timings = {config: self._bench(*args, config=config, **kwargs) for config in pruned_configs}
            bench_end = time.time()
            self.bench_time = bench_end - bench_start
            self.cache[key] = builtins.min(timings, key=timings.get)
            full_nargs = {**self.nargs, **kwargs, **self.cache[key].all_kwargs()}
            self.pre_hook(full_nargs, reset_only=True)
            self.configs_timings = timings
        config = self.cache[key]
    else:
        config = self.configs[0]
    self.best_config = config
    if os.getenv("TRITON_PRINT_AUTOTUNING", None) == "1" and not used_cached_result:
        print(f"Triton autotuning for function {self.base_fn.__name__} finished after "
              f"{self.bench_time:.2f}s; best config selected: {self.best_config};")
    if config.pre_hook is not None:
        full_nargs = {**self.nargs, **kwargs, **config.all_kwargs()}
        config.pre_hook(full_nargs)
    ret = self.fn.run(
        *args,
        **kwargs,
        **config.all_kwargs(),
    )
    self.nargs = None
    return ret

def _bench(self, *args, config, **meta):
    from ..compiler.errors import CompileTimeAssertionFailure

    # check for conflicts, i.e. meta-parameters both provided
    # as kwargs and by the autotuner
    conflicts = meta.keys() & config.kwargs.keys()
    if conflicts:
        raise ValueError(f"Conflicting meta-parameters: {', '.join(conflicts)}."
                         " Make sure that you don't re-define auto-tuned symbols.")
    # augment meta-parameters with tunable ones
    current = dict(meta, **config.all_kwargs())
    full_nargs = {**self.nargs, **current}

    def kernel_call():
        if config.pre_hook:
            config.pre_hook(full_nargs)
        self.pre_hook(full_nargs)
        try:
            self.fn.run(
                *args,
                **current,
            )
        except Exception as e:
            try:
                self.post_hook(full_nargs, exception=e)
            finally:
                # Throw exception raised by `self.fn.run`
                raise

        self.post_hook(full_nargs, exception=None)

    try:
        return self.do_bench(kernel_call, quantiles=(0.5, 0.2, 0.8))
    except (OutOfResources, CompileTimeAssertionFailure):
        return [float("inf"), float("inf"), float("inf")]

elif (len(self.reset_to_zero) > 0 or len(self.restore_value) > 0):

    def _pre_hook(kwargs, reset_only=False):
        for name in self.reset_to_zero:
            kwargs[name].zero_()
        if not reset_only:
            self.restore_copies = {name: kwargs[name].clone() for name in self.restore_value}

    self.pre_hook = _pre_hook

if post_hook:
    self.post_hook = post_hook
    self.user_defined_post_hook = True
elif len(self.restore_value) > 0:

    def _post_hook(kwargs, exception):
        for name in self.restore_value:
            kwargs[name].copy_(self.restore_copies[name])
        self.restore_copies = {}

    self.post_hook = _post_hook

def prune_configs(self, kwargs):
    pruned_configs = self.configs
    if self.early_config_prune:
        pruned_configs = self.early_config_prune(self.configs, self.nargs, **kwargs)
    if self.perf_model:
        top_k = self.configs_top_k
        if isinstance(top_k, float) and top_k <= 1.0:
            top_k = int(len(self.configs) * top_k)
        if len(pruned_configs) > top_k:
            est_timing = {
                config: self.perf_model(
                    **self.nargs,
                    **kwargs,
                    **config.all_kwargs(),
                )
                for config in pruned_configs
            }
            pruned_configs = sorted(est_timing.keys(), key=lambda x: est_timing[x])[:top_k]
    return pruned_configs

def all_kwargs(self):
    return {
        **self.kwargs, **{
            k: v
            for (k, v) in (
                ("num_warps", self.num_warps),
                ("num_ctas", self.num_ctas),
                ("num_stages", self.num_stages),
                ("num_buffers_warp_spec", self.num_buffers_warp_spec),
                ("num_consumer_groups", self.num_consumer_groups),
                ("reg_dec_producer", self.reg_dec_producer),
                ("reg_inc_consumer", self.reg_inc_consumer),
                ("maxnreg", self.maxnreg),
            ) if v is not None
        }
    }

def __init__(self, key, override=False, dump=False):
    self.key = key
    self.lock_path = None
    if dump:
        self.cache_dir = os.getenv("TRITON_DUMP_DIR", "").strip() or default_dump_dir()
        self.cache_dir = os.path.join(self.cache_dir, self.key)
        self.lock_path = os.path.join(self.cache_dir, "lock")
        os.makedirs(self.cache_dir, exist_ok=True)
    elif override:
        self.cache_dir = os.getenv("TRITON_OVERRIDE_DIR", "").strip() or default_override_dir()
        self.cache_dir = os.path.join(self.cache_dir, self.key)
    else:
        # create cache directory if it doesn't exist
        self.cache_dir = os.getenv("TRITON_CACHE_DIR", "").strip() or default_cache_dir()
        if self.cache_dir:
            self.cache_dir = os.path.join(self.cache_dir, self.key)
            self.lock_path = os.path.join(self.cache_dir, "lock")
            os.makedirs(self.cache_dir, exist_ok=True)
        else:
            raise RuntimeError("Could not create or locate cache dir")

def get_group(self, filename: str) -> Optional[Dict[str, str]]:
    grp_filename = f"__grp__{filename}"
    if not self.has_file(grp_filename):
        return None
    grp_filepath = self._make_path(grp_filename)
    with open(grp_filepath) as f:
        grp_data = json.load(f)
    child_paths = grp_data.get("child_paths", None)
    # Invalid group data.
    if child_paths is None:
        return None
    result = {}
    for c, p in child_paths.items():
        if os.path.exists(p):
            result[c] = p
    return result

# Note a group of pushed files as being part of a group
def put_group(self, filename: str, group: Dict[str, str]) -> str:
    if not self.cache_dir:
        raise RuntimeError("Could not create or locate cache dir")
    grp_contents = json.dumps({"child_paths": group})
    grp_filename = f"__grp__{filename}"
    return self.put(grp_contents, grp_filename, binary=False)

def _base64(key):
    # Assume key is a hex string.
    return base64.urlsafe_b64encode(bytes.fromhex(key)).decode("utf-8").rstrip("=")


def get_cache_manager(key) -> CacheManager:
    import os

    user_cache_manager = os.environ.get("TRITON_CACHE_MANAGER", None)
    global __cache_cls
    global __cache_cls_nme

    if user_cache_manager is not None and user_cache_manager != __cache_cls_nme:
        module_path, clz_nme = user_cache_manager.split(":")
        module = importlib.import_module(module_path)
        __cache_cls = getattr(module, clz_nme)
        __cache_cls_nme = user_cache_manager

    return __cache_cls(_base64(key))
